function onChange(control, oldValue, newValue, isLoading) {
	if (isLoading || newValue == '') {
		return;
	}

	var ga = new GlideAjax('global.GetPropertiesAjax');
	ga.addParam('sysparm_name', 'getProperty');
	ga.addParam('sysparm_properties', JSON.stringify(['x_asat_csc.sys_id.service_offering.solicitacao_de_validacao_de_documentacao_admissao_digital']));
	ga.getXMLAnswer(function (response) {
		var propertyValue = JSON.parse(response);
		if (newValue == propertyValue[0]) {
			g_form.setMandatory('rh_description', false);
			g_form.setReadOnly('rh_description', true);
			g_form.setValue('rh_description', `Olá, RH.

Foi aberto um chamado devido à pendência de documentação e/ou necessidade de regularização cadastral para a admissão do(a) candidato(a).
Solicitamos, por gentileza, a verificação da pendência e o retorno por meio do chamado, para que possamos dar continuidade ao processo de admissão.
Para os casos de irregularidade na Receita Federal, segue abaixo o detalhamento de acordo com a situação cadastral informada:
Pendente de Regularização: o contribuinte deixou de entregar alguma Declaração do Imposto de Renda da Pessoa Física (DIRPF) dos últimos cinco anos.
Suspensa: o cadastro do contribuinte está incorreto ou incompleto.
Cancelada: o CPF foi cancelado por multiplicidade, em virtude de decisão administrativa ou judicial.
Titular Falecido: quando for incluído o ano de óbito.
Nula: foi constatada fraude na inscrição e o CPF foi anulado.
Data de Nascimento: a data de nascimento informada no ato da admissão, está divergente da existente no cadastro da Receita Federal.
Ficamos no aguardo do seu retorno.
Obrigada.`);

		} else {
			g_form.setMandatory('rh_description', true);
			g_form.setReadOnly('rh_description', false);
			g_form.setValue('rh_description', '');
		}
	});

}

