	var pattern = /^\(?[1-9]{2}\)? ?(?:[2-8]|9[1-9])[0-9]{3}?[0-9]{4}$/g;
	if(!pattern.test(aux)){
		g_form.addErrorMessage('Por favor preencher o campo "Telefone de contato do Condutor" com um número de telefone válido, no formato (DDD)9XXXXXXXX. Exemplo: (11)912345678 ou 11912345678');
		g_form.setValue('rh_drivers_phone', '');
	}else{
		var arrayzao = aux.split("");
		var celular = false;
		if(arrayzao.length == 12){
			celular = true;
		}
		if(arrayzao[0] != "("){
			var finalzao = "(";
			var i = 0;
			arrayzao.forEach(function(item){
				/*if(i == 6 && celular){
					finalzao = finalzao + "-";
				}
				if(i == 5 && !celular){
					finalzao = finalzao + "-";
				}*/
				if(i == 2){
					finalzao = finalzao+")"+item;
				}else{
					finalzao = finalzao+item;
				}
				i++;

			});
			g_form.setValue('rh_drivers_phone',  finalzao);
		}

	}

}

