function onChange(control, oldValue, newValue, isLoading) {
   if (newValue == '') {

		g_form.setValue("rh_delivery_kit_type_adress","");
		g_form.setValue("rh_logradouro", "");
		g_form.setValue("rh_neighborhood","");
		g_form.setValue("rh_county", "");
		g_form.setValue("rh_state", "");

      return;
   }

	var ga = new GlideAjax("global.CepAjaxV2");
	ga.addParam('sysparm_name','getAddress');
	ga.addParam('sysparm_cep', newValue.toString().trim());
	ga.getXMLAnswer(function(response) {

		var resp = JSON.parse(response);

		if (resp.hasOwnProperty("cep")) {

			var first_name = resp.logradouro.split(" ");

			g_form.setValue("rh_delivery_kit_type_adress",first_name[0]);
			g_form.setValue("rh_logradouro", resp.logradouro);
			g_form.setValue("rh_neighborhood",resp.bairro);
			g_form.setValue("rh_county", resp.localidade);
			g_form.setValue("rh_state", resp.uf);

		} else {

			g_form.addErrorMessage("CEP não localizado ou inválido");
		}
	});

}

