function onChange(control, oldValue, newValue, isLoading) {
	if (isLoading || newValue == '') {
		return;



	}

	g_form.hideFieldMsg('corporate_cellphone', true);

	var mask1 = /\([1-9]{2}\) [9]{0,1}[0-9]{4}\-[0-9]{4}$/;

	if (mask1.test(newValue)) {
		return;
	}

	//somente números
	var regex =/^[0-9]*$/;
	var phone = "";

	if (!regex.test(newValue.trim())) {
		g_form.clearValue("corporate_cellphone");
		g_form.showFieldMsg('corporate_cellphone', 'Permitido digitar somente números, Exemplo: (11) 91234-5678 ou 11912345678', 'info');

		return;
	}

	if (newValue.length < 10 || newValue.length > 11) {
		g_form.clearValue("corporate_cellphone");
		g_form.showFieldMsg('corporate_cellphone', 'Por favor preencher o campo com um número de telefone válido, no formato (DDD)9XXXX-XXXX. Exemplo: (11)91234-5678 ou 11912345678', 'info');
		return;
	}

	g_form.hideFieldMsg('corporate_cellphone', true);

	if(newValue.length == 10){
		phone =  '('+newValue.slice(0,2)+') '+newValue.slice(2,6)+'-'+newValue.slice(6,10);
		g_form.setValue("corporate_cellphone",phone);
	}

	if(newValue.length == 11){
		phone = "("+newValue.slice(0,2)+") "+newValue.slice(2,7)+'-'+newValue.slice(7,11);

		g_form.setValue("corporate_cellphone",phone);
	}
}

