	}

	var strData = newValue;
	var partesData = strData.split("/");
	var data = new Date(partesData[2], partesData[1] - 1, partesData[0]);
	var str_data_referencia = g_form.getValue('reference_date').split("/");
	var data_referencia = new Date(str_data_referencia[2], str_data_referencia[1] - 1, str_data_referencia[0]);

	if(data > new Date()){

		g_form.addErrorMessage('Não é permitido datas futuras no campo "Data da folga".');
		g_form.setValue('dayoff_date', '');

	}
	else if(data < data_referencia){

		g_form.addErrorMessage('O campo "Data da folga" não pode ser menor que o campo "Data de referência".');
		g_form.setValue('dayoff_date', '');

	}

