function onChange(control, oldValue, newValue, isLoading) {
    var cpfCnpj = newValue.replace(/[^\d]+/g, '');
    if (isLoading || newValue == '' || oldValue.replace(/[^\d]+/g, '') == cpfCnpj) {
        return;
    }

    var fieldName = "dependent_cpf";

    // Valida se possui letras
    var regex = /[a-zA-Z]+/; //  /^[0-9]+$/;  
    if (newValue.match(regex)) {
        g_form.setValue(fieldName, '');
        g_form.showFieldMsg(fieldName, 'Somente números!', 'error');
        return;
    }

    var numbers = newValue.replace(/[^\d]+/ig, '').toString();


    if (!(numbers.length == 11)) {
        g_form.setValue(fieldName, '');
        g_form.showFieldMsg(fieldName, 'CPF inválido', 'error');
        return;
    }

    function _fnFormatCPF(cpf) {
        try {
            if (typeof cpf !== 'string')
                throw "Data type invalid: " + typeof cpf;

            if (cpf.toString().replace(/[^0-9]/ig, '').length != 11)
                throw 'Quantidade de números inválida para um CPF';

            return cpf.toString().replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, "$1.$2.$3-$4");

        } catch (e) {
            //console.error(e);
        }
    }


    function _fnCpfIsValid(cpf) {

        try {

            if (typeof cpf !== 'string')
                throw "Data type invalid: " + typeof cnpj;

            var Soma;
            var Resto;
            Soma = 0;

            if (
                cpf == "00000000000" ||
                cpf == "11111111111" ||
                cpf == "22222222222" ||
                cpf == "33333333333" ||
                cpf == "44444444444" ||
                cpf == "55555555555" ||
                cpf == "66666666666" ||
                cpf == "77777777777" ||
                cpf == "88888888888" ||
                cpf == "99999999999"
            )
                return false;

            for (i = 1; i <= 9; i++) Soma = Soma + parseInt(cpf.substring(i - 1, i)) * (11 - i);
            Resto = (Soma * 10) % 11;

            if ((Resto == 10) || (Resto == 11)) Resto = 0;
            if (Resto != parseInt(cpf.substring(9, 10))) return false;

            Soma = 0;
            for (i = 1; i <= 10; i++) Soma = Soma + parseInt(cpf.substring(i - 1, i)) * (12 - i);
            Resto = (Soma * 10) % 11;

            if ((Resto == 10) || (Resto == 11)) Resto = 0;
            if (Resto != parseInt(cpf.substring(10, 11))) return false;
            return true;
        } catch (e) {
            throw "Error: " + e;
        }

    }
    var config = {
        type: null,
        data: null,
        execute: false
    };

    if (numbers.length == 11) {
        if (!_fnCpfIsValid(numbers)) {
            g_form.setValue(fieldName, '');
            g_form.showFieldMsg(fieldName, 'O CPF digitado não é válido!', 'error');
            //g_form.addErrorMessage("O CPF digitado não é válido");
            return;
        }
        g_form.setValue(fieldName, _fnFormatCPF(numbers));
        config = {
            type: 'cpf',
            data: numbers
        };
    } else {
        if (numbers.length == 0) {
            g_form.setValue(fieldName, "");
            return;
        }
        config = {
            type: 'codigo',
            data: numbers
        };
    }




}

function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || !newValue) return;

   var m = String(newValue).trim().match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
   if (!m) {
      g_form.clearValue('age');
      g_form.addErrorMessage('Data de nascimento inválida (use DD/MM/AAAA).');
      return;
   }

   var dd = parseInt(m[1], 10);
   var mm = parseInt(m[2], 10) - 1;
   var yyyy = parseInt(m[3], 10);

   var birth = new Date(Date.UTC(yyyy, mm, dd));
   if (
      isNaN(birth.getTime()) ||
      birth.getUTCFullYear() !== yyyy ||
      birth.getUTCMonth() !== mm ||
      birth.getUTCDate() !== dd
   ) {
      g_form.clearValue('age');
      g_form.addErrorMessage('Data de nascimento inválida.');
      return;
   }

   var now = new Date();
   var todayUTC = new Date(Date.UTC(
      now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()
   ));

   if (birth > todayUTC) {
      g_form.clearValue('age');
      g_form.addErrorMessage('Data de nascimento no futuro.');
      return;
   }

   var age = todayUTC.getUTCFullYear() - birth.getUTCFullYear();

   var anniversaryThisYear = new Date(Date.UTC(
      todayUTC.getUTCFullYear(), birth.getUTCMonth(), birth.getUTCDate()
   ));

   if (todayUTC < anniversaryThisYear) {
      age--;
   }

   if (age < 0) age = 0;

   g_form.setValue('age', String(age));
}

