function onLoad() {

	var so = this.get_form.getDisplayValue("service_offering");

	if(so == 'Solicitação de reembolso de Faltas e Atrasos' || so == 'Solicitação de reembolso de Faltas e Atrasos'){
		g_form.setVisible('vs_return_credit_basic_basket_card_set_2', true);
