		g_form.setMandatory('vs_return_credit_mom_card_set_2', true);
	} else {

		g_form.setMandatory('vs_return_credit_basic_basket_card_set_2', false);
		g_form.setMandatory('vs_return_credit_mom_card_set_2', false);

