	}
}

function onSubmit() {

    var mr = this.get_form.getValue("vs_reembolso_de_faltas_e_atrasos_2");
    if (mr != '' && mr != 'undefined' && mr != null) {
        var par = JSON.parse(mr);

        var matriculas = [];

        for (var i = 0; i < par.length; i++) {
            matriculas.push(par[i].vs_employee_registration_set_2);
        }

        var primeiraLinha = matriculas[0];

        if (primeiraLinha != g_form.getValue('vs_employee_registration_set_2')) {
            g_form.addErrorMessage('Colaborador informado diferente do colaborador inserido anteriormente.');

            return false;
        }
    }
}

function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    // Oferta: Solicitação de Pagamento de horas extras/ Adicional Noturno / Hora extra Feriado Item: Divergência no Ponto
    var so = g_service_catalog.parent.getValue("service_offering") ? g_service_catalog.parent.getValue("service_offering").toString() : "";

    var matricula = g_form.getValue('vs_employee_registration_set_2');
    var data = g_form.getValue('vs_date_of_occurrence_set_2');
    var verba = g_form.getValue('vs_leaf_money_set_2');

    var ga = new GlideAjax("global.GetPropertiesAjax");
    ga.addParam("sysparm_name", "getProperty");
    ga.addParam("sysparm_properties", JSON.stringify(["x_asat_csc.service_offering.solicitacao_de_pagamento.sys_id"]));
    ga.getXMLAnswer(function (response) {

        var properties = JSON.parse(response)[0];
        if (properties.toString() != so) {

            if (matricula != "" && data != "" && verba != "") {

                var ga = new GlideAjax('global.ReembolsoFaltasAtrasosAjax');
                ga.addParam('sysparm_name', 'checkChamados');
                ga.addParam('sysparm_matricula', matricula);
                ga.addParam('sysparm_data', data);
                ga.addParam('sysparm_verba', verba);
                ga.getXMLAnswer(function (response) {
                    var answer = response;

                    if (answer) {
                        g_form.clearValue('vs_employee_registration_set_2');
                        g_form.clearValue('vs_employees_name_set_2');
                        g_form.clearValue('vs_amount_of_hours_set_2');
                        g_form.clearValue('vs_date_of_occurrence_set_2');
                        g_form.clearValue('vs_code_description_of_occurrence_set_2');
                        g_form.clearValue('vs_type_of_hours_set_2');
                        g_form.clearValue('vs_leaf_money_set_2');
                        g_form.clearValue('vs_reason_set_2');
                        g_form.clearValue('vs_return_credit_basic_basket_card_set_2');
                        g_form.clearValue('vs_return_credit_mom_card_set_2');

                        g_form.addErrorMessage('O colaborador informado, já possui uma solicitação gerada de número ' + answer);
                        return;
                    }
                });
            } else {
                g_form.clearValue('vs_reason_set_2');
                g_form.addErrorMessage('Preencha os campos Matrícula do colaborador, Data da ocorrência e Verba da folha');
            }
        } else {
            if (matricula == "") {
                g_form.clearValue('vs_reason_set_2');
                g_form.addErrorMessage('Preencha o campo Matrícula do colaborador.');
            }
        }
    });
}

