    //Type appropriate comment here, and begin script below

    var mr = this.get_form.getValue("vs_reembolso_de_faltas_e_atrasos_2");
    if (mr != '' && mr != 'undefined' && mr != null) {

        var par = JSON.parse(mr);
        if (this.get_form.getDisplayValue("service_offering") == 'Solicitação de pagamento de horas extras/adicional noturno/hora extra feriado') {

