            g_form.setValue('cr_description_vs', awser.name);
            g_form.setValue('cr_vs', formattedValue);
        } else {
			g_form.setValue('cr_vs', '');
            g_form.addErrorMessage('Não existe cr informado na base');
            g_form.showFieldMsg('cr_vs', 'Formato CR 1234-123 ou 1234123', 'info');
            g_form.setValue('cr_description_vs', '');

        }
    });

}

function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   switch (newValue) {
      case '1':
         g_form.addInfoMessage("Atenção! Anexar documentação comprobatória: documento que gerou a suspensão de contrato de trabalho do colaborador.");
         break;
      case '2':
         g_form.addInfoMessage("Atenção! Anexar o espelho de ponto, contendo o registro de faltas e a tratativa referente ao abandono.");
         break;
      case '3':
         g_form.addInfoMessage("Atenção! Anexar evidência de desligamento ou término do contrato do aprendiz anterior.");
         break;
      case '4':
         g_form.addInfoMessage("Atenção! Anexar evidência de desligamento ou movimentação do PCD anterior.");
         break;
      case '5':
         g_form.addInfoMessage("Atenção! Anexar evidência da necessidade de reintegração, confirmada pelo Jurídico ou pelo RH.");
         break;
      case '8':
         g_form.addInfoMessage("Atenção! Anexar documento que comprove o afastamento no sistema de RH ou no INSS, informando o período.");
         break;
   }
}

function onSubmit() {

	var arrValid = ['1', '2', '3', '4', '5', '8'];
	var value = g_form.getValue("reason_vs");

	if (arrValid.indexOf(value) !== -1) {
		this.get_form.setMandatory("Attachments_manutencao", true);
		this.get_form.setMandatory("aux_widget_manutencao", true);
	}
}

